<script lang="ts">
 import { onMount } from 'svelte'; import InlineError from '$lib/components/InlineError.svelte'; import { listAdminFeedback, updateAdminFeedbackStatus } from '$lib/api/admin'; import { ApiError } from '$lib/api/types'; import type { AdminFeedbackSummary } from '$lib/api/types'; let feedback:AdminFeedbackSummary[]=[]; let error=''; async function load(){try{feedback=(await listAdminFeedback()).feedback;}catch(err){error=err instanceof ApiError?err.message:'Unable to load feedback.';}} async function setStatus(id:string,status:string){await updateAdminFeedbackStatus(id,status); await load();} onMount(load);
</script><section class="admin-page"><header class="admin-header"><div><h1>Feedback</h1><p>Review early user feedback and update status.</p></div><nav class="admin-nav"><a href="/admin">Overview</a><a href="/admin/users">Users</a><a href="/admin/packages">Packages</a><a href="/admin/feedback">Feedback</a><a href="/admin/supporters">Supporters</a><a href="/admin/audit">Audit</a></nav></header><InlineError message={error}/><section class="panel"><table><thead><tr><th>Title</th><th>User</th><th>Status</th><th>Message</th><th>Action</th></tr></thead><tbody>{#each feedback as item}<tr><td>{item.title}<br/><small>{item.category}</small></td><td>{item.user_email}</td><td>{item.status}</td><td>{item.message}</td><td><select value={item.status} onchange={(e) => setStatus(item.id, e.currentTarget.value)}><option>open</option><option>reviewed</option><option>planned</option><option>closed</option></select></td></tr>{/each}</tbody></table></section></section>
